insert into public.vocabulary_items
(vocabulary_id,term,part_of_speech,core_meaning,senses,word_family,collocations,status)
values
('vocab_casual','casual','adjective','relaxed and not formal, especially in style, clothes or behaviour','[{"senseId":"casual_1","meaning":"relaxed and not formal, especially in style, clothes or behaviour","acceptedParaphrases":["relaxed","not formal"],"masteryContexts":[{"contextId":"u9_21_casual_meaning","text":"The party is casual, so there is no need to wear a suit.","meaning":"relaxed and not formal","wrongMeanings":["very smart and expensive","carefully planned","serious and traditional"]},{"contextId":"u9_21_casual_paraphrase","text":"Her casual greeting, \"Hey, how’s it going?\", surprised the new manager.","meaning":"relaxed in manner","wrongMeanings":["rude and aggressive in manner","shy and quiet in manner","strict and serious in manner"]}],"situationDistractors":["A man wore a suit and tie to a wedding ceremony.","A student planned every minute of her presentation carefully.","A judge spoke seriously to the court.","A waiter wore a black suit and a bow tie at a dinner.","A student planned her speech word by word.","A soldier stood very straight during a ceremony."],"gapDistractors":[{"contextId":"u9_21_casual_gap_1","answer":"casual","wrong":["banned","underlying","tech-savvy"]},{"contextId":"u9_21_casual_gap_2","answer":"casual","wrong":["banned","portable","underlying"]},{"contextId":"u9_21_casual_gap_3","answer":"casual","wrong":["banned","portable","tech-savvy"]}],"spellingErrors":["casuel","cashual","casul","cassual","casueal","casuall"],"masteryPassages":[{"passageId":"u9_21_casual_passage_1","contextId":"u9_21_casual_gap_1","text":"The invitation said \"no need to dress up\". Most guests arrived in jeans, T-shirts and other ____ clothes.","answer":"casual"},{"passageId":"u9_21_casual_passage_2","contextId":"u9_21_casual_gap_2","text":"His email began \"Hey there!\" and ended with three emojis. The manager thought the tone was too ____ for a job application.","answer":"casual"}],"contextDependentParaphrases":[],"wrongParaphrases":["smart","strict","carefully planned"],"misleadingDistractors":["carefully planned in great detail","smart and suitable for a ceremony","very serious and strict"],"teacherNote":"Adjective: relaxed and not formal (casual clothes, a casual conversation, casual style). Boundary: casual often describes clothes and manner; informal often describes language and situations; both are opposites of formal. A second meaning, \"not regular\" (casual work), is not taught here. The adverb casually is taught in the Word Family pathway."}]'::jsonb,'[]'::jsonb,'["casual clothes","a casual conversation","a casual style"]'::jsonb,'live'),
('vocab_workforce','workforce','noun','all the people who work in a company, industry or country','[{"senseId":"workforce_1","meaning":"all the people who work in a company, industry or country","acceptedParaphrases":["all the workers","the employees"],"masteryContexts":[{"contextId":"u9_22_workforce_meaning","text":"As digital natives join the workforce, offices are using more messaging apps and fewer phones.","meaning":"all the people who work","wrongMeanings":["all the people who buy products","all the machines in offices","all the rules at work"]},{"contextId":"u9_22_workforce_paraphrase","text":"The factory plans to train its entire workforce to use the new machines.","meaning":"all the employees of a company","wrongMeanings":["all the managers of a company","all the customers of a company","all the products of a company"]}],"situationDistractors":["A company bought three new robots for its packing line.","A shop counted how much money it had made in a month.","Hundreds of customers queued to buy a new phone.","A shop counted how many customers came in on Saturday.","A factory bought new machines to make bottles.","A company reported its profits for the year."],"gapDistractors":[{"contextId":"u9_22_workforce_gap_1","answer":"workforce","wrong":["accuracy","frustration","perception"]},{"contextId":"u9_22_workforce_gap_2","answer":"workforce","wrong":["accuracy","perception","frustration"]},{"contextId":"u9_22_workforce_gap_3","answer":"workforce","wrong":["accuracy","frustration","perception"]}],"spellingErrors":["workfource","work-forse","workforse","workfroce","wokforce","workfoce"],"masteryPassages":[{"passageId":"u9_22_workforce_passage_1","contextId":"u9_22_workforce_gap_1","text":"The company has offices in six countries. Its ____ of over ten thousand people speaks more than twenty languages.","answer":"workforce"},{"passageId":"u9_22_workforce_passage_2","contextId":"u9_22_workforce_gap_2","text":"More young people than ever now finish university. When they join the ____, they bring strong digital skills with them.","answer":"workforce"}],"contextDependentParaphrases":[],"wrongParaphrases":["all the customers","all the machines","all the profits"],"misleadingDistractors":["the machines used in a factory","the money a company earns","the people who buy a product"],"teacherNote":"Noun (usually singular): all the people who work for a company, in an industry or in a country (the workforce, a skilled workforce, join the workforce). Can take a singular or plural verb in British English. It is a compound with no useful taught family, so Word Families is not counted."}]'::jsonb,'[]'::jsonb,'["join the workforce","a skilled workforce","the entire workforce"]'::jsonb,'live'),
('vocab_generation_9','generation','noun','all the people born and living at about the same time, considered as a group','[{"senseId":"generation_9_1","meaning":"all the people born and living at about the same time, considered as a group","acceptedParaphrases":["age group","people born around the same time"],"masteryContexts":[{"contextId":"u9_23_generation_9_meaning","text":"Each new generation seems to invent its own slang words.","meaning":"people born and growing up at the same time","wrongMeanings":["people who work in the same company","people who live in the same street","people who speak the same language"]},{"contextId":"u9_23_generation_9_paraphrase","text":"My grandparents’ generation prefers phone calls, while we prefer messages.","meaning":"the people of one age group considered together","wrongMeanings":["the people of one family considered together","the people of one country considered together","the people of one profession considered together"]}],"situationDistractors":["A group of colleagues from different ages worked on a project together.","A family of four lives in a small flat in the city.","A decade passed between the first and second versions of the game.","A group of classmates worked on a science project.","A team of colleagues met to discuss a plan.","A family moved into a new house in the suburbs."],"gapDistractors":[{"contextId":"u9_23_generation_9_gap_1","answer":"generation","wrong":["accuracy","frustration","purpose"]},{"contextId":"u9_23_generation_9_gap_2","answer":"generation","wrong":["accuracy","frustration","purpose"]},{"contextId":"u9_23_generation_9_gap_3","answer":"generation","wrong":["accuracy","frustration","perception"]}],"spellingErrors":["genaration","generatoin","generasion","generetion","generaton","jeneration"],"masteryPassages":[{"passageId":"u9_23_generation_9_passage_1","contextId":"u9_23_generation_9_gap_1","text":"My grandparents wrote letters and my parents sent emails. My ____ mostly sends voice messages.","answer":"generation"},{"passageId":"u9_23_generation_9_passage_2","contextId":"u9_23_generation_9_gap_2","text":"Each new ____ of teenagers seems to invent its own slang. Words that were cool ten years ago now sound old-fashioned.","answer":"generation"}],"contextDependentParaphrases":[],"wrongParaphrases":["family","team","decade"],"misleadingDistractors":["a family that lives in the same house","a group of people who work together","a period of ten years"],"teacherNote":"Noun (countable): all the people born at about the same time (the younger generation, my parents’ generation, a generation gap). Unit 9 uses it for differences in communication between age groups; Unit 1 taught it for sports and free time. The verb generate is a different sense and is not taught here; Word Families is not counted for this sense."}]'::jsonb,'[]'::jsonb,'["the younger generation","my parents’ generation","a generation gap"]'::jsonb,'live'),
('vocab_perception','perception','noun','the way that someone thinks about or understands something or someone','[{"senseId":"perception_1","meaning":"the way that someone thinks about or understands something or someone","acceptedParaphrases":["view","impression"],"masteryContexts":[{"contextId":"u9_24_perception_meaning","text":"The public perception of video games has changed: many people now see them as a form of art.","meaning":"the way people think about something","wrongMeanings":["the price that people pay for something","the history of something","the rules about something"]},{"contextId":"u9_24_perception_paraphrase","text":"Her perception that nobody liked her turned out to be completely wrong.","meaning":"a belief or impression about a situation","wrongMeanings":["a fear about a situation","a fact proved about a situation","a plan for a situation"]}],"situationDistractors":["Scientists proved that the new medicine worked in a large study.","A boy typed so quickly that he finished first in the class.","A girl hurt her ankle while running and had to stop.","A scientist measured the temperature of the water.","A runner trained every morning to become faster.","A girl cut her finger while cooking."],"gapDistractors":[{"contextId":"u9_24_perception_gap_1","answer":"perception","wrong":["workforce","accuracy","conference"]},{"contextId":"u9_24_perception_gap_2","answer":"perception","wrong":["workforce","conference","introduction"]},{"contextId":"u9_24_perception_gap_3","answer":"perception","wrong":["workforce","conference","accuracy"]}],"spellingErrors":["perseption","perceptoin","percepsion","preception","perceptin","perceptione"],"wordFamilyForms":[{"form":"perception","partOfSpeech":"noun","example":"Social media can change our perception of what is normal.","pedagogicallyUseful":true},{"form":"perceive","partOfSpeech":"verb","example":"Older people sometimes perceive teenagers as rude.","pedagogicallyUseful":true,"altExample":"Many people perceive online friendships as less real."},{"form":"perceptive","partOfSpeech":"adjective","example":"A perceptive reader notices what the writer does not say directly.","pedagogicallyUseful":true,"altExample":"Her perceptive comments helped the team understand the problem."}],"masteryPassages":[{"passageId":"u9_24_perception_passage_1","contextId":"u9_24_perception_gap_1","text":"Many people used to think video games were a waste of time. That ____ has changed, and some universities now offer courses in game design.","answer":"perception"},{"passageId":"u9_24_perception_passage_2","contextId":"u9_24_perception_gap_2","text":"Lin believed that her classmates did not like her. Her ____ was wrong: they simply thought she was shy.","answer":"perception"}],"contextDependentParaphrases":[],"wrongParaphrases":["proven fact","physical pain","working speed"],"misleadingDistractors":["a fact that has been proved by research","the ability to work quickly","a feeling of physical pain"],"teacherNote":"Noun: the way someone thinks about or understands something (public perception, perception of/that, change people’s perceptions). Boundary: a perception is an opinion or impression, not necessarily a fact. A second meaning, noticing with the senses, is related but not the focus. The verb perceive and the adjective perceptive are taught in the Word Family pathway."}]'::jsonb,'["perceive","perceptive"]'::jsonb,'["public perception","change people’s perception","a common perception that"]'::jsonb,'live'),
('vocab_non_verbal','non-verbal','adjective','not using words or speech, for example using gestures, facial expressions or body language','[{"senseId":"non_verbal_1","meaning":"not using words or speech, for example using gestures, facial expressions or body language","acceptedParaphrases":["without words","using body language"],"masteryContexts":[{"contextId":"u9_25_non_verbal_meaning","text":"Crossing your arms is a non-verbal signal that some people read as unfriendly.","meaning":"communicated without words","wrongMeanings":["written in a short message","spoken in a loud voice","recorded on video"]},{"contextId":"u9_25_non_verbal_paraphrase","text":"Video calls make it harder to notice non-verbal cues such as small changes in someone’s face.","meaning":"using body language rather than speech","wrongMeanings":["using written words rather than speech","using loud sounds rather than words","using emojis rather than letters"]}],"situationDistractors":["A student wrote a detailed letter of complaint to the council.","A boy shouted the answer across the classroom.","A lecturer used many long technical words in his talk.","A girl read a long poem aloud to the class.","A boy wrote a detailed email to his teacher.","A presenter spoke into a microphone for an hour."],"gapDistractors":[{"contextId":"u9_25_non_verbal_gap_1","answer":"non-verbal","wrong":["portable","banned","tech-savvy"]},{"contextId":"u9_25_non_verbal_gap_2","answer":"non-verbal","wrong":["portable","tech-savvy","optional"]},{"contextId":"u9_25_non_verbal_gap_3","answer":"non-verbal","wrong":["portable","banned","optional"]}],"spellingErrors":["non-verbel","non-vurbal","non-verble","non-verball","nonverbel","non-vebal"],"masteryPassages":[{"passageId":"u9_25_non_verbal_passage_1","contextId":"u9_25_non_verbal_gap_1","text":"He said he was happy, but his crossed arms and tired face told a different story. His ____ signals showed how he really felt.","answer":"non-verbal"},{"passageId":"u9_25_non_verbal_passage_2","contextId":"u9_25_non_verbal_gap_2","text":"In some countries, nodding means \"no\" rather than \"yes\". Travellers should learn about ____ communication before they visit.","answer":"non-verbal"}],"contextDependentParaphrases":[],"wrongParaphrases":["written","spoken aloud","recorded"],"misleadingDistractors":["written down on paper","spoken very loudly","using difficult vocabulary"],"teacherNote":"Adjective (hyphenated): not using words (non-verbal communication, non-verbal signals, non-verbal cues). Includes gestures, facial expressions, eye contact and posture. Opposite: verbal. It is a compound with no taught family, so Word Families is not counted."}]'::jsonb,'[]'::jsonb,'["non-verbal communication","non-verbal signals","non-verbal cues"]'::jsonb,'live'),
('vocab_underlying','underlying','adjective','real and important, but not immediately obvious or easy to see','[{"senseId":"underlying_1","meaning":"real and important, but not immediately obvious or easy to see","acceptedParaphrases":["hidden but real","basic and not obvious"],"masteryContexts":[{"contextId":"u9_26_underlying_meaning","text":"Doctors try to treat the underlying cause of an illness, not just the symptoms.","meaning":"the real cause that is not immediately obvious","wrongMeanings":["the most obvious cause that everyone sees","a minor cause that does not matter","the cause that appears last"]},{"contextId":"u9_26_underlying_paraphrase","text":"The advert looks funny, but its underlying message is about road safety.","meaning":"hidden beneath the surface but important","wrongMeanings":["clearly printed on the surface","added as a joke","meant only for children"]}],"situationDistractors":["The instructions were printed in large letters on the front of the box.","A teacher ignored a small spelling mistake because it did not matter.","A student added one extra sentence just before handing in her essay.","The price was printed clearly on the front of the box.","A boy forgot one small detail that did not matter.","A teacher added a last-minute question to the test."],"gapDistractors":[{"contextId":"u9_26_underlying_gap_1","answer":"underlying","wrong":["portable","tech-savvy","banned"]},{"contextId":"u9_26_underlying_gap_2","answer":"underlying","wrong":["portable","tech-savvy","optional"]},{"contextId":"u9_26_underlying_gap_3","answer":"underlying","wrong":["portable","tech-savvy","casual"]}],"spellingErrors":["underlaying","underliing","underlyng","undrlying","underlieing","underliyng"],"masteryPassages":[{"passageId":"u9_26_underlying_passage_1","contextId":"u9_26_underlying_gap_1","text":"The students said they were late because of traffic. However, the ____ reason was that they did not want to miss breakfast.","answer":"underlying"},{"passageId":"u9_26_underlying_passage_2","contextId":"u9_26_underlying_gap_2","text":"Changing the colour of the app did not stop users leaving. The ____ problem was that it was too slow.","answer":"underlying"}],"contextDependentParaphrases":[],"wrongParaphrases":["clearly visible","unimportant","added later"],"misleadingDistractors":["clearly written on the surface","unimportant and easy to ignore","added at the last minute"],"teacherNote":"Adjective (always before a noun): real and important but not obvious (the underlying cause/reason/problem/message). Boundary: underlying is about what lies beneath the surface; obvious is the opposite. The fixed phrase \"underlying meaning\" is taught as a separate target. The verb underlie is formal and rare at this level, so Word Families is not counted."}]'::jsonb,'[]'::jsonb,'["the underlying cause","the underlying problem","an underlying message"]'::jsonb,'live'),
('vocab_differentiate','differentiate','verb','to see or show the difference between two or more things or people','[{"senseId":"differentiate_1","meaning":"to see or show the difference between two or more things or people","acceptedParaphrases":["tell the difference","distinguish"],"masteryContexts":[{"contextId":"u9_27_differentiate_meaning","text":"A good reader can differentiate between facts and the writer’s opinions.","meaning":"to recognise how two things are not the same","wrongMeanings":["to mix up two things","to combine two things","to copy two things"]},{"contextId":"u9_27_differentiate_paraphrase","text":"The new phone tries to differentiate itself from competitors with a much better camera.","meaning":"to show how something is not the same as others","wrongMeanings":["to make itself the same as others","to join together with others","to sell itself more cheaply than others"]}],"situationDistractors":["A factory made thousands of identical bottles every day.","Two schools joined together to form one large school.","A boy mixed up his twin cousins’ names all evening.","A machine printed one hundred identical tickets.","Two clubs joined together to form one bigger club.","A girl mixed up the names of two new classmates."],"gapDistractors":[{"contextId":"u9_27_differentiate_gap_1","answer":"differentiate","wrong":["survive","launch","ban"]},{"contextId":"u9_27_differentiate_gap_2","answer":"differentiate","wrong":["survive","launch","recommend"]},{"contextId":"u9_27_differentiate_gap_3","answer":"differentiate","wrong":["survive","launch","ban"]}],"spellingErrors":["diferentiate","differenciate","differentate","differantiate","diffrentiate","differentiat"],"wordFamilyForms":[{"form":"differentiate","partOfSpeech":"verb","example":"Young children cannot always differentiate between adverts and videos.","pedagogicallyUseful":true},{"form":"different","partOfSpeech":"adjective","example":"Each region has a different way of greeting people.","pedagogicallyUseful":true,"altExample":"The twins have very different personalities."},{"form":"difference","partOfSpeech":"noun","example":"Can you see the difference between the two photos?","pedagogicallyUseful":true,"altExample":"There is a big difference between texting and talking."}],"masteryPassages":[{"passageId":"u9_27_differentiate_passage_1","contextId":"u9_27_differentiate_gap_1","text":"Fake news websites often look very professional. It can be hard to ____ between real news and invented stories.","answer":"differentiate"},{"passageId":"u9_27_differentiate_passage_2","contextId":"u9_27_differentiate_gap_2","text":"The twins look exactly the same. Only their mother can ____ one from the other at first glance.","answer":"differentiate"}],"contextDependentParaphrases":[],"wrongParaphrases":["combine","copy","confuse"],"misleadingDistractors":["to make two things exactly the same","to join two groups together","to forget which thing is which"],"teacherNote":"Verb: to see or show the difference between things (differentiate between A and B, differentiate A from B). Boundary: differentiate and distinguish are close synonyms; both are more formal than \"tell the difference\". The noun differentiation is taught in the Word Family pathway; the related noun difference and adjective different are also used there."}]'::jsonb,'["different","difference"]'::jsonb,'["differentiate between","differentiate A from B","difficult to differentiate"]'::jsonb,'live'),
('vocab_physical','physical','adjective','existing in a form that you can touch or see, not digital or imagined','[{"senseId":"physical_1","meaning":"existing in a form that you can touch or see, not digital or imagined","acceptedParaphrases":["real and solid","not digital"],"masteryContexts":[{"contextId":"u9_28_physical_meaning","text":"Many banks have closed their physical branches because customers now bank online.","meaning":"existing as a real building, not online","wrongMeanings":["existing only online","very old and historic","run by the government"]},{"contextId":"u9_28_physical_paraphrase","text":"Teenagers send thousands of messages, but they still need physical contact with friends.","meaning":"real and in person rather than digital","wrongMeanings":["imaginary rather than real","online rather than in person","written rather than spoken"]}],"situationDistractors":["A student kept all her notes in a cloud folder on her laptop.","A child invented an imaginary friend to talk to.","A girl felt happy when she remembered her holiday.","A boy saved his photos to an online account.","A writer imagined a city that does not exist.","A girl felt nervous about her exam results."],"gapDistractors":[{"contextId":"u9_28_physical_gap_1","answer":"physical","wrong":["banned","tech-savvy","underlying"]},{"contextId":"u9_28_physical_gap_2","answer":"physical","wrong":["banned","tech-savvy","underlying"]},{"contextId":"u9_28_physical_gap_3","answer":"physical","wrong":["banned","tech-savvy","underlying"]}],"spellingErrors":["phisical","physicle","fysical","physcal","phyiscal","physicall"],"masteryPassages":[{"passageId":"u9_28_physical_passage_1","contextId":"u9_28_physical_gap_1","text":"The bookshop closed its ____ store in the high street. It now sells books only through its website.","answer":"physical"},{"passageId":"u9_28_physical_passage_2","contextId":"u9_28_physical_gap_2","text":"A photo of your ticket on your phone is not enough. You must bring a ____ copy printed on paper.","answer":"physical"}],"contextDependentParaphrases":[],"wrongParaphrases":["online","imaginary","emotional"],"misleadingDistractors":["existing only on a computer","imagined and not real","related to feelings and thoughts"],"teacherNote":"Adjective: existing in a real, touchable form rather than digitally or in the mind (a physical shop, physical copy, physical contact). Unit 9 uses it to contrast with virtual and digital. A second meaning, relating to the body (physical exercise), is common but not the focus here. The adverb physically is taught in the Word Family pathway."}]'::jsonb,'[]'::jsonb,'["a physical shop","a physical copy","physical contact"]'::jsonb,'live'),
('vocab_platform','platform','noun','a website, app or system that people use to communicate, share content or offer services','[{"senseId":"platform_1","meaning":"a website, app or system that people use to communicate, share content or offer services","acceptedParaphrases":["online service","website or app for sharing"],"masteryContexts":[{"contextId":"u9_29_platform_meaning","text":"Each social media platform attracts a slightly different age group.","meaning":"a website or app used for sharing content","wrongMeanings":["a piece of computer equipment","a group of software engineers","a password for an account"]},{"contextId":"u9_29_platform_paraphrase","text":"The conference took place on a video platform, so speakers joined from six countries.","meaning":"a digital system used for communicating","wrongMeanings":["a room for formal meetings","a cable that carries signals","a person who manages calls"]}],"situationDistractors":["A technician carried a heavy server into the office.","A programmer wrote the code for a new game.","A boy chose a strong password for his email account.","A technician replaced the battery in a laptop.","A programmer fixed a bug in her code.","A boy changed the password on his phone."],"gapDistractors":[{"contextId":"u9_29_platform_gap_1","answer":"platform","wrong":["frustration","accuracy","perception"]},{"contextId":"u9_29_platform_gap_2","answer":"platform","wrong":["frustration","accuracy","perception"]},{"contextId":"u9_29_platform_gap_3","answer":"platform","wrong":["frustration","perception","clause"]}],"spellingErrors":["platfrom","platfom","plattform","platforme","platfourm","pletform"],"masteryPassages":[{"passageId":"u9_29_platform_passage_1","contextId":"u9_29_platform_gap_1","text":"Teachers post homework and students upload their work on the same online ____. It also sends reminders before deadlines.","answer":"platform"},{"passageId":"u9_29_platform_passage_2","contextId":"u9_29_platform_gap_2","text":"The singer released her new song on a streaming ____. Within hours, it had been played a million times.","answer":"platform"}],"contextDependentParaphrases":[],"wrongParaphrases":["hardware","password","programmer"],"misleadingDistractors":["a large piece of computer equipment","a person who writes software","a password used to protect an account"],"teacherNote":"Noun (countable): a website, app or digital system that people use to communicate or share content (a social media platform, an online platform, a learning platform). Boundary: a railway platform or a stage platform are other meanings, not taught here. It has no useful taught family, so Word Families is not counted."}]'::jsonb,'[]'::jsonb,'["a social media platform","an online platform","a streaming platform"]'::jsonb,'live'),
('vocab_virtual','virtual','adjective','created by computers or happening online, rather than existing in the physical world','[{"senseId":"virtual_1","meaning":"created by computers or happening online, rather than existing in the physical world","acceptedParaphrases":["online","computer-generated"],"masteryContexts":[{"contextId":"u9_30_virtual_meaning","text":"During the lockdown, students attended virtual classes from their bedrooms.","meaning":"happening online rather than in person","wrongMeanings":["happening in a large hall","happening very early in the morning","happening only once a year"]},{"contextId":"u9_30_virtual_paraphrase","text":"With a headset, you can walk around a virtual version of ancient Rome.","meaning":"created by a computer to look real","wrongMeanings":["built from real stone and wood","painted by hand on paper","shown in a museum"]}],"situationDistractors":["A potter made a bowl by hand from clay.","Ten people sat around a table in a real meeting room.","The village still celebrates the festival in the traditional way.","A carpenter made a table from a piece of oak.","Twenty people met in a village hall to plan a festival.","A family celebrated the new year in the traditional way."],"gapDistractors":[{"contextId":"u9_30_virtual_gap_1","answer":"virtual","wrong":["banned","tech-savvy","underlying"]},{"contextId":"u9_30_virtual_gap_2","answer":"virtual","wrong":["banned","tech-savvy","underlying"]},{"contextId":"u9_30_virtual_gap_3","answer":"virtual","wrong":["banned","optional","underlying"]}],"spellingErrors":["virtuel","vertual","virtul","virtural","virtuall","viirtual"],"masteryPassages":[{"passageId":"u9_30_virtual_passage_1","contextId":"u9_30_virtual_gap_1","text":"The museum is closed for repairs, but you can still visit it online. Its ____ tour shows every room in 3D.","answer":"virtual"},{"passageId":"u9_30_virtual_passage_2","contextId":"u9_30_virtual_gap_2","text":"The manager was in Dubai and the team was in London. They held a ____ meeting using video cameras and headsets.","answer":"virtual"}],"contextDependentParaphrases":[],"wrongParaphrases":["handmade","in person","traditional"],"misleadingDistractors":["made by hand from natural materials","happening in a real room with people present","very old and traditional"],"teacherNote":"Adjective: created by computer technology or happening online rather than in the physical world (a virtual meeting, virtual reality, a virtual tour). Opposite here: physical / face-to-face / in person. The noun virtual reality is a common collocation. The adverb virtually means \"almost\" and is a different sense, so Word Families is not counted."}]'::jsonb,'[]'::jsonb,'["a virtual meeting","virtual reality","a virtual tour"]'::jsonb,'live')
